(6444173, 956057, 54645, '<td valign="top">Ha, from <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=35804" rel="nofollow" target="_blank">rkt</a>''s splendid beauty to a gritty <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=11769" rel="nofollow" target="_blank">jmritz</a>, who needs this crap when you can hop on a pony and meander down the lane to communicate in person. One of a few entries that sought to present a pathway to symbolism.  9</td>', 'Ha, from  rkt''s splendid beauty to a gritty  jmritz, who needs this crap when you can hop on a pony and meander down the lane to communicate in person. One of a few entries that sought to present a pathway to symbolism.  9', '2011-06-15 02:59:38.000000', NULL, 1),
(6444174, 956834, 54645, '<td valign="top">I hate it when this happens.</td>', 'I hate it when this happens.', '2011-06-15 03:01:09.000000', NULL, 1),
(6444177, 956964, 54645, '<td valign="top">Strikes me as the work of Clive. Textured subject and light, fleeting glimpses of past and current beauty. I particularly like the black hat/whatever it is at the top of the frame. A well chosen, and placed, concept of aging. Hanging over our heads to be embraced or futily battled. The dark eyes suggest the one time beauty queen has failed to accept this gracefully. No mercy in tyranny. 10</td>', 'Strikes me as the work of Clive. Textured subject and light, fleeting glimpses of past and current beauty. I particularly like the black hat/whatever it is at the top of the frame. A well chosen, and placed, concept of aging. Hanging over our heads to be embraced or futily battled. The dark eyes suggest the one time beauty queen has failed to accept this gracefully. No mercy in tyranny. 10', '2011-06-15 03:10:40.000000', NULL, 1),
