INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6449627, 956873, 68504, '<td valign="top">the wonder of the neighborhood, so clean, so dirty, so elegant, so whatever.</td>', 'the wonder of the neighborhood, so clean, so dirty, so elegant, so whatever.', '2011-06-21 22:09:08.000000', NULL, 1),
(6449630, 956968, 124815, '<td valign="top">A very peaceful image here, in my view. I''m fighting with a title that wants to be more formidable than the image - are we talking "vacuism"? Could be my ignorance. I stay with my reading of this beautiful dreamy image of a painter''s brushes at rest.</td>', 'A very peaceful image here, in my view. I''m fighting with a title that wants to be more formidable than the image - are we talking "vacuism"? Could be my ignorance. I stay with my reading of this beautiful dreamy image of a painter''s brushes at rest.', '2011-06-21 22:09:23.000000', NULL, 1),
(6449631, 956920, 124815, '<td valign="top">Beautiful geometry here! Well balanced.</td>', 'Beautiful geometry here! Well balanced.', '2011-06-21 22:09:28.000000', NULL, 1),
(6449632, 956541, 50864, '<td valign="top">Beautiful bokeh  behind that lovely web</td>', 'Beautiful bokeh  behind that lovely web', '2011-06-21 22:09:42.000000', NULL, 1),
(6449633, 957019, 68504, '<td valign="top">o</td>', 'o', '2011-06-21 22:09:59.000000', NULL, 1),
(6449634, 956483, 68504, '<td valign="top">like</td>', 'like', '2011-06-21 22:10:28.000000', NULL, 1),
(6449635, 956589, 124815, '<td valign="top">Persuasive and nostalgic.</td>', 'Persuasive and nostalgic.', '2011-06-21 22:10:48.000000', NULL, 1),
(6449636, 956997, 68504, '<td valign="top">a kind of genius.</td>', 'a kind of genius.', '2011-06-21 22:10:59.000000', NULL, 1),
(6449640, 956177, 76335, '<td valign="top">I like it. Low key, very simple. It needed no sharpening though (referring to the halo around the outline of the chair). Really, what could it add?</td>', 'I like it. Low key, very simple. It needed no sharpening though (referring to the halo around the outline of the chair). Really, what could it add?', '2011-06-21 22:11:55.000000', NULL, 1),
(6449642, 956978, 76335, '<td valign="top">Interesting. I feel like I''m missing part of thre story.</td>', 'Interesting. I feel like I''m missing part of thre story.', '2011-06-21 22:14:20.000000', NULL, 1),
(6449647, 956615, 76335, '<td valign="top">A wonderful graphic image -- not sure how well it holds up as a still life.</td>', 'A wonderful graphic image -- not sure how well it holds up as a still life.', '2011-06-21 22:16:38.000000', NULL, 1),
(6449649, 956945, 50864, '<td valign="top">I like the colors.  Wonder what it all means. Are the pills for malaria? And the flowers and bread?  very interesting and nicely done.</td>', 'I like the colors.  Wonder what it all means. Are the pills for malaria? And the flowers and bread?  very interesting and nicely done.', '2011-06-21 22:17:42.000000', NULL, 1),
(6449652, 957019, 50864, '<td valign="top">Great title for this very nice image.</td>', 'Great title for this very nice image.', '2011-06-21 22:20:37.000000', NULL, 1),
(6449657, 956895, 50864, '<td valign="top">Beautiful tones and light.  I rarely do this but I just have to say that without the ring and bottle I would thinks it would be exquisite.</td>', 'Beautiful tones and light.  I rarely do this but I just have to say that without the ring and bottle I would thinks it would be exquisite.', '2011-06-21 22:26:35.000000', NULL, 1),
(6449658, 956299, 76335, '<td valign="top">Sucked dry of all color, this works.</td>', 'Sucked dry of all color, this works.', '2011-06-21 22:26:39.000000', NULL, 1),
(6449659, 956615, 11769, '<td valign="top">The essence of our existence.</td>', 'The essence of our existence.', '2011-06-21 22:31:33.000000', NULL, 1),
(6449660, 956979, 11769, '<td valign="top">Beautiful</td>', 'Beautiful', '2011-06-21 22:32:10.000000', NULL, 1),
(6449662, 956873, 76335, '<td valign="top">An image that makes me happy that I didn''t let this challenge go by without voting. This is... yes, I''ll say it... beautiful.<br/> <br/>This gets a ten from me. It couldn''t be set up, and by taking no care in framing it (or taking so much care in <i>not</i> framing it), you don''t try to turn it into something it isn''t. It''s just as the title reads. Find your own symbolism.</td>', 'An image that makes me happy that I didn''t let this challenge go by without voting. This is... yes, I''ll say it... beautiful. This gets a ten from me. It couldn''t be set up, and by taking no care in framing it (or taking so much care in not framing it), you don''t try to turn it into something it isn''t. It''s just as the title reads. Find your own symbolism.', '2011-06-21 22:33:06.000000', NULL, 1),
(6449663, 956993, 11769, '<td valign="top">Excellent</td>', 'Excellent', '2011-06-21 22:34:10.000000', NULL, 1),
(6449664, 956750, 11769, '<td valign="top">So cool</td>', 'So cool', '2011-06-21 22:36:01.000000', NULL, 1),
(6449667, 956187, 76335, '<td valign="top">Simply perfect. Rampant consumerism. It''s in our faces constantly, but we never see it. Or maybe we stopped looking. Or noticing. Thanks for the reminder.</td>', 'Simply perfect. Rampant consumerism. It''s in our faces constantly, but we never see it. Or maybe we stopped looking. Or noticing. Thanks for the reminder.', '2011-06-21 22:38:05.000000', NULL, 1),
(6449668, 956057, 76335, '<td valign="top">Not over all the noise. Which is the point, of course. Poignant.</td>', 'Not over all the noise. Which is the point, of course. Poignant.', '2011-06-21 22:38:08.000000', NULL, 1),
(6449669, 956971, 76335, '<td valign="top">Strangely beautiful.</td>', 'Strangely beautiful.', '2011-06-21 22:38:11.000000', NULL, 1),
(6449671, 956964, 76335, '<td valign="top">Well stated, pefectly illustrated.</td>', 'Well stated, pefectly illustrated.', '2011-06-21 22:38:51.000000', NULL, 1),
(6449673, 956987, 124815, '<td valign="top">Yes, it has the look of a picture from a biography (not Kafka''s though). A very nice shot. (I voted a while ago)</td>', 'Yes, it has the look of a picture from a biography (not Kafka''s though). A very nice shot. (I voted a while ago)', '2011-06-21 22:39:51.000000', NULL, 1),
(6449681, 956991, 124815, '<td valign="top">Just a touch too much background IMO. These kind of "vanitas" seem to be better when more condensed or with a very dark background. As I play with the position of the picture on my screen, I find it very effective if the entire top, from the top of the apple would be cropped (the skull would have to be repositioned somehow). <br/>Of course that I am splitting hair now but I do it only with really good images. (I voted early but had no time for comments)</td>', 'Just a touch too much background IMO. These kind of "vanitas" seem to be better when more condensed or with a very dark background. As I play with the position of the picture on my screen, I find it very effective if the entire top, from the top of the apple would be cropped (the skull would have to be repositioned somehow). Of course that I am splitting hair now but I do it only with really good images. (I voted early but had no time for comments)', '2011-06-21 22:45:26.000000', NULL, 1),
(6449683, 956826, 124815, '<td valign="top">Well done. Very old world. Bumped it up.</td>', 'Well done. Very old world. Bumped it up.', '2011-06-21 22:46:04.000000', NULL, 1),
(6449688, 957019, 124815, '<td valign="top">It should move me, but it doesn''t. Perhaps because I see too distinctly the flower ... perhaps because I did not get to that level of subtlety yet ....<br/>(I voted early but had no time for comments)</td>', 'It should move me, but it doesn''t. Perhaps because I see too distinctly the flower ... perhaps because I did not get to that level of subtlety yet ....(I voted early but had no time for comments)', '2011-06-21 22:52:59.000000', NULL, 1),
(6449692, 957011, 124815, '<td valign="top">Clean and lovely. Bumped it up.</td>', 'Clean and lovely. Bumped it up.', '2011-06-21 22:54:26.000000', NULL, 1),
(6449695, 956895, 124815, '<td valign="top">I like the image although the tonality and treatment does not go well with this wine! I am still searching for the meaning, but again, it''s a very nice shot. (I voted early but had no time for comments)</td>', 'I like the image although the tonality and treatment does not go well with this wine! I am still searching for the meaning, but again, it''s a very nice shot. (I voted early but had no time for comments)', '2011-06-21 22:57:34.000000', NULL, 1),
(6449700, 956979, 124815, '<td valign="top">Well felt and nostalgic. I doubt that the rosemary (?) little branches belong there. Perhaps just the empty bowl. It''s always the case when one arranges a still life. Should be just as the say: when you dress up, upon leaving home take out one piece of jewelry that you wear. (I voted early but had no time for comments)</td>', 'Well felt and nostalgic. I doubt that the rosemary (?) little branches belong there. Perhaps just the empty bowl. It''s always the case when one arranges a still life. Should be just as the say: when you dress up, upon leaving home take out one piece of jewelry that you wear. (I voted early but had no time for comments)', '2011-06-21 23:03:08.000000', NULL, 1),
(6449702, 956944, 124815, '<td valign="top">Beautiful tonality! You probably got a few of these comments. (I voted early but had no time for comments)</td>', 'Beautiful tonality! You probably got a few of these comments. (I voted early but had no time for comments)', '2011-06-21 23:05:53.000000', NULL, 1),
