(6450187, 957019, 11769, '<td valign="top">Love the dark</td>', 'Love the dark', '2011-06-22 10:32:09.000000', NULL, 0),
(6450188, 956918, 27812, '<td valign="top">You''re on a roll babe!<br/> <br/>I recovered from my op in an after care place which also houses old people with issues. I met a few people with dementia there and that contributed to my massive paradigm shift. Thanks for sharing a very special creative moment with us.</td>', 'You''re on a roll babe! I recovered from my op in an after care place which also houses old people with issues. I met a few people with dementia there and that contributed to my massive paradigm shift. Thanks for sharing a very special creative moment with us.', '2011-06-22 10:32:23.000000', NULL, 0),
(6450192, 956997, 11769, '<td valign="top">Love the photographer''s comments. There is a wonderful sense of humor in this. I think.</td>', 'Love the photographer''s comments. There is a wonderful sense of humor in this. I think.', '2011-06-22 10:37:46.000000', NULL, 0),
